-- Official SG past questions: 2017 autumn, text-representable questions 21–30.
-- Question 25 is omitted because its answer options are embedded in an image table.
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29a-2017-q21','exam-sg','マルウェア・C&Cサーバ','standard','single_choice','ボットネットにおいてC&Cサーバが果たす役割はどれか。','[{"id":"a","text":"遠隔操作可能なマルウェアに情報収集及び攻撃活動を指示する。"},{"id":"b","text":"電子商取引事業者に偽のデジタル証明書の発行を命令する。"},{"id":"c","text":"不正なWebコンテンツのテキスト，画像及びレイアウト情報を管理する。"},{"id":"d","text":"踏み台となる複数のサーバからの通信を制御し遮断する。"}]','"a"','正解はア。C&Cサーバはボットネットに指令を送り，感染端末の動作を遠隔制御する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q22','exam-sg','DNS・キャッシュポイズニング','standard','single_choice','DNSキャッシュポイズニングに分類される攻撃内容はどれか。','[{"id":"a","text":"DNSサーバのバージョン情報を入手し，セキュリティホールを特定する。"},{"id":"b","text":"PCが参照するDNSサーバに偽のドメイン情報を注入し，利用者を偽装サーバに誘導する。"},{"id":"c","text":"サービス妨害のためDNSサーバを踏み台にして再帰的問合せを大量に行う。"},{"id":"d","text":"内部情報を得るためDNSサーバのゾーン情報をまとめて転送させる。"}]','"b"','正解はイ。偽の名前解決情報をDNSキャッシュに登録させ，利用者を攻撃者が用意したサイトへ誘導する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q23','exam-sg','公開鍵暗号・RSA','standard','single_choice','非常に大きな数の素因数分解が困難なことを利用した公開鍵暗号方式はどれか。','[{"id":"a","text":"AES"},{"id":"b","text":"DH"},{"id":"c","text":"DSA"},{"id":"d","text":"RSA"}]','"d"','正解はエ。RSAは大きな合成数の素因数分解が困難であることを安全性の根拠とする公開鍵暗号方式である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q24','exam-sg','デジタル署名・真正性','standard','single_choice','デジタル署名における署名鍵の使い方と目的のうち，適切なものはどれか。','[{"id":"a","text":"受信者が署名鍵で暗号文を元のメッセージに戻せるようにする。"},{"id":"b","text":"送信者が固定文字列を付加して暗号化し，受信者が改ざん部位を特定できるようにする。"},{"id":"c","text":"送信者が署名鍵で署名を作成してメッセージに付加し，受信者が送信者を確認できるようにする。"},{"id":"d","text":"送信者が署名鍵でメッセージを暗号化し，内容を第三者に分からなくする。"}]','"c"','正解はウ。デジタル署名は送信者の真正性と改ざんの有無を確認するために用い，本文の秘匿を目的としない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q26','exam-sg','PKI・ルート認証局','standard','single_choice','ルート認証局についての記述はどれか。','[{"id":"a","text":"UNIX系OSでrootアカウントの権限でプログラムを実行するために利用者が使用する。"},{"id":"b","text":"上位の認証局が発行した証明書によって，自らの認証局としての正当性を示す。"},{"id":"c","text":"信頼される第三者機関として，認証局運用規程を公開している。"},{"id":"d","text":"侵入の痕跡を隠し，管理者レベルのアクセス権限を得るために使用される。"}]','"c"','正解はウ。ルート認証局はPKI階層の最上位に位置し，信頼を維持するため認証局運用規程などを公開する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q27','exam-sg','マルウェア・ワーム','standard','single_choice','トロイの木馬と比較したときのワームの特徴はどれか。','[{"id":"a","text":"勝手にファイルを暗号化して正常に読めなくする。"},{"id":"b","text":"単独のプログラムとして不正な動作を行う。"},{"id":"c","text":"特定の条件になるまで活動せず待機する。"},{"id":"d","text":"ネットワークやリムーバブルメディアを媒介として自ら感染を広げる。"}]','"d"','正解はエ。ワームは自ら複製し，ネットワークや外部メディアを介して感染を拡大する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q28','exam-sg','公開鍵暗号・鍵の使い分け','standard','single_choice','公開鍵暗号方式で，AさんからBさんへ他人に秘密にしたい文章を送るとき，暗号化に用いる鍵はどれか。','[{"id":"a","text":"Aさんの公開鍵"},{"id":"b","text":"Aさんの秘密鍵"},{"id":"c","text":"Bさんの公開鍵"},{"id":"d","text":"共通鍵"}]','"c"','正解はウ。機密性を確保してBさんに送る場合，送信者は受信者Bさんの公開鍵で暗号化し，Bさんが秘密鍵で復号する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q29','exam-sg','TLS・HTTPS','standard','single_choice','HTTP over TLS（HTTPS）を用いて実現できるものはどれか。','[{"id":"a","text":"Webサーバ上のファイルの改ざん検知"},{"id":"b","text":"Webブラウザが動作するPC上のマルウェア検査"},{"id":"c","text":"Webブラウザが動作するPCに対する侵入検知"},{"id":"d","text":"デジタル証明書によるサーバ認証"}]','"d"','正解はエ。HTTPSはTLSを利用し，通信の暗号化や完全性保護，デジタル証明書によるサーバ認証を提供する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja'),
('sg-official-h29a-2017-q30','exam-sg','脆弱性診断・ファジング','standard','single_choice','ファジングの説明はどれか。','[{"id":"a","text":"社内ネットワークに接続するPCのマルウェア感染を検査し，要件を満たすPCだけ接続を許可する。"},{"id":"b","text":"ソースコードの構文を機械的に確認して特定パターンから脆弱性を検出する。"},{"id":"c","text":"ソースコードを読み，チェックリストに従って脆弱性を検出する。"},{"id":"d","text":"問題を引き起こしそうな多様なデータを自動生成して入力し，応答や挙動から脆弱性を検出する。"}]','"d"','正解はエ。ファジングは不正・異常な入力を大量に与え，ソフトウェアの応答や異常終了などから脆弱性を検出する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_qs.pdf','ja');
